const assets = $('Fetch Active Assets').item.json;
const ccList = $('Fetch Cost Center Codes').item.json;

const ccMap = {};
(ccList || []).forEach(cc => { ccMap[cc.id] = cc.code; });

const now = new Date();
const period = now.getFullYear() + '-' + String(now.getMonth() + 1).padStart(2, '0');
const today = now.toISOString().split('T')[0];

const logRows = [];
const assetUpdates = [];
const warrantyAlerts = [];
const eolCandidates = [];

for (const a of assets) {
  if (!a.purchase_cost_eur || !a.useful_life_months) continue;

  const depreciableBase = (a.purchase_cost_eur || 0) - (a.residual_value || 0);
  const monthlyDep = depreciableBase / a.useful_life_months;

  const currentBook = a.current_book_value ?? a.purchase_cost_eur;
  const accum = a.accumulated_depreciation ?? 0;

  // Don't depreciate below residual value
  const actualDep = Math.min(monthlyDep, Math.max(0, currentBook - (a.residual_value || 0)));
  if (actualDep <= 0) continue;

  const newAccum      = Math.round((accum + actualDep) * 100) / 100;
  const newBookValue  = Math.round((currentBook - actualDep) * 100) / 100;

  const ccCode = ccMap[a.cost_center_id] || 'UNKNOWN';

  logRows.push({
    id:                   undefined,  // let DB generate
    asset_id:             a.id,
    period,
    depreciation_amount:  Math.round(actualDep * 100) / 100,
    book_value_before:    currentBook,
    book_value_after:     newBookValue,
    method_used:          'straight_line',
    gl_account:           '6820',
    cost_center_code:     ccCode,
    posted:               false
  });

  assetUpdates.push({
    id:                      a.id,
    accumulated_depreciation: newAccum,
    current_book_value:       newBookValue
  });

  // Warranty alerts
  if (a.warranty_expiry) {
    const expDate = new Date(a.warranty_expiry);
    const daysToExpiry = Math.floor((expDate - now) / (1000 * 60 * 60 * 24));
    if (daysToExpiry <= 90 && daysToExpiry > 0) {
      warrantyAlerts.push({
        asset_id:   a.id,
        asset_tag:  a.asset_tag,
        make:       a.make,
        model:      a.model,
        expiry:     a.warranty_expiry,
        days_left:  daysToExpiry,
        urgency:    daysToExpiry <= 30 ? 'critical' : 'warning'
      });
    }
  }

  // EOL candidates: book value < 10% of purchase cost AND warranty expired AND incidents > 3
  const bookValuePct = (newBookValue / a.purchase_cost_eur) * 100;
  const warrantyExpired = a.warranty_expiry ? new Date(a.warranty_expiry) < now : false;
  const highIncidents = (a.incident_count || 0) > 3;

  if (bookValuePct < 10 && warrantyExpired && highIncidents) {
    eolCandidates.push({
      asset_id:       a.id,
      asset_tag:      a.asset_tag,
      make:           a.make,
      model:          a.model,
      book_value:     newBookValue,
      book_value_pct: Math.round(bookValuePct * 10) / 10,
      incident_count: a.incident_count,
      branch_id:      a.branch_id,
      cost_center_id: a.cost_center_id,
      purchase_cost:  a.purchase_cost_eur
    });
  }
}

return [{ json: { period, today, logRows, assetUpdates, warrantyAlerts, eolCandidates } }];

// Build a PATCH array for each asset via PostgREST
// We'll emit one item per asset update for the HTTP node to process
const updates = $input.item.json.assetUpdates || [];
if (updates.length === 0) return [{ json: { updated: 0 } }];

// Return each update as a separate item
return updates.map(u => ({ json: u }));

// Aggregate results back
const calc = $('Calculate Depreciation Batch').item.json;
return [{ json: {
  period:           calc.period,
  log_rows_written: calc.logRows.length,
  assets_updated:   calc.assetUpdates.length,
  warranty_alerts:  calc.warrantyAlerts,
  eol_candidates:   calc.eolCandidates,
  has_warranty_alerts: calc.warrantyAlerts.length > 0,
  has_eol_candidates:  calc.eolCandidates.length > 0
} }];

const raw = $input.item.json.content[0].text.trim();
let parsed;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : raw);
} catch(e) {
  parsed = { tickets: [] };
}
return [{ json: parsed }];
